var engine = new LabEngine();
var line = engine.MakeLine("L1");
var first = engine.MakeCall("C1", line);
var second = engine.MakeCall("C2", line);
var alias = first;
alias.Emit(LabCallState.Active);
Console.WriteLine(first.State);  // Active
Console.WriteLine(second.State); // Created
Console.WriteLine(ReferenceEquals(alias, first)); // True
Console.WriteLine(ReferenceEquals(first, second)); // False

var wrong = new LabLine("L1");
string observed = "NotRegistered";
wrong.Register(200);
wrong.Changed += e => observed = e.State;
Console.WriteLine($"actual={wrong.State} UI={observed}");
// actual=Registered UI=NotRegistered
var right = new LabLine("L2");
right.Changed += e => observed = e.State;
right.Register(200);
Console.WriteLine($"actual={right.State} UI={observed}");
// actual=Registered UI=Registered

